const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..', '..');

function readStore(world, key) {
  const raw = world.localStorage.getItem(key);
  assert(raw, 'localStorage key ' + key + ' missing');
  return JSON.parse(raw);
}

function nextId(todos) {
  let max = 0;
  for (const t of todos) {
    if (typeof t.id === 'number' && t.id > max) max = t.id;
  }
  return max + 1;
}

function seedTodo(world, title, completed) {
  const todos = world.localStorage.getItem('todos-vanilla');
  const list = todos ? JSON.parse(todos) : [];
  if (!list.some((t) => t.title === title)) {
    list.push({ id: nextId(list), title, completed });
    world.localStorage.setItem('todos-vanilla', JSON.stringify(list));
  }
  // Re-render from the seeded store: dispatch hashchange, which the app handles by rendering.
  world.window.dispatchEvent(new world.window.Event('hashchange'));
}

function findItem(world, title) {
  const items = world.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) return li;
  }
  return null;
}

Given('the app has loaded', function () {});

Then('the global flag {string} is set to a truthy value', function (flag) {
  const value = this.window[flag];
  assert(
    value,
    'global flag "' + flag + '" is not set to a truthy value (got ' + JSON.stringify(value) + ')'
  );
});

Then('the {string} section is hidden', function (sel) {
  const el = this.document.querySelector(sel);
  assert(el, 'element ' + sel + ' not found');
  assert.strictEqual(el.hidden, true, sel + ' should be hidden');
});

Then('the new-todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(this.document.activeElement, input, 'new-todo input should be focused');
});

When('the user adds the todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

Then('the todo {string} is present in the list', function (title) {
  assert(findItem(this, title), 'todo ' + title + ' not present in the list');
});

Then('the new-todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'new-todo input should be empty');
});

When('the user enters {string} in the new-todo input and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

Then('no todo item is present in the list', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'expected no todo items, found ' + items.length);
});

Given('the todo {string} is active', function (title) {
  seedTodo(this, title, false);
});

Given('the todo {string} is completed', function (title) {
  seedTodo(this, title, true);
});

When('the user clicks the toggle-all checkbox', function () {
  const ta = this.document.getElementById('toggle-all');
  ta.checked = !ta.checked;
  ta.dispatchEvent(new this.window.Event('change'));
});

Then('the todo {string} has the {string} class', function (title, cls) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  assert(li.classList.contains(cls), 'todo ' + title + ' missing class ' + cls);
});

Then('the todo {string} does not have the {string} class', function (title, cls) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  assert(!li.classList.contains(cls), 'todo ' + title + ' should not have class ' + cls);
});

Then('the toggle-all checkbox is checked', function () {
  const ta = this.document.getElementById('toggle-all');
  assert.strictEqual(ta.checked, true, 'toggle-all should be checked');
});

Then('the toggle-all checkbox is unchecked', function () {
  const ta = this.document.getElementById('toggle-all');
  assert.strictEqual(ta.checked, false, 'toggle-all should be unchecked');
});

When('the user clicks the checkbox of {string}', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const cb = li.querySelector('.toggle');
  cb.checked = !cb.checked;
  cb.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user double-clicks the label of {string}', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

Then('the todo {string} is in editing mode', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  assert(li.classList.contains('editing'), 'todo ' + title + ' should be in editing mode');
});

Then('the edit input of {string} is focused', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const edit = li.querySelector('.edit');
  assert.strictEqual(this.document.activeElement, edit, 'edit input of ' + title + ' should be focused');
});

When('the user edits the label of {string} to {string} and presses Enter', function (title, newTitle) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const edit = li.querySelector('.edit');
  edit.value = newTitle;
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

Then('the todo {string} is not present in the list', function (title) {
  assert(!findItem(this, title), 'todo ' + title + ' should not be present');
});

Then('the todo {string} is not in editing mode', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  assert(!li.classList.contains('editing'), 'todo ' + title + ' should not be in editing mode');
});

When('the user edits the label of {string} to {string} and blurs', function (title, newTitle) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const edit = li.querySelector('.edit');
  edit.value = newTitle;
  edit.dispatchEvent(new this.window.Event('blur'));
});

When('the user clears the edit input of {string} and presses Enter', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const edit = li.querySelector('.edit');
  edit.value = '';
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

When('the user edits the label of {string} to {string} and presses Escape', function (title, newTitle) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const edit = li.querySelector('.edit');
  edit.value = newTitle;
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
});

Then('every todo item has a {string} button', function (cls) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert(items.length > 0, 'expected at least one todo item');
  for (const li of items) {
    assert(li.querySelector('button.' + cls), 'todo item missing ' + cls + ' button');
  }
});

Then('the todo-count shows {string}', function (text) {
  const count = this.document.querySelector('.todo-count');
  assert.strictEqual(count.textContent, text, 'todo-count should show "' + text + '" but showed "' + count.textContent + '"');
});

When('the user clicks the clear-completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
});

Then('the clear-completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.strictEqual(btn.hidden, true, 'clear-completed button should be hidden');
});

Then('the localStorage key {string} contains a record with title {string}', function (key, title) {
  const data = readStore(this, key);
  assert(Array.isArray(data) && data.some((t) => t.title === title), 'no record with title ' + title);
});

Then('the todo {string} is stored as active', function (title) {
  const data = readStore(this, 'todos-vanilla');
  const t = data.find((x) => x.title === title);
  assert(t, 'no stored record for ' + title);
  assert.strictEqual(t.completed, false, title + ' should be stored as active');
});

Then('the todo {string} is stored as completed', function (title) {
  const data = readStore(this, 'todos-vanilla');
  const t = data.find((x) => x.title === title);
  assert(t, 'no stored record for ' + title);
  assert.strictEqual(t.completed, true, title + ' should be stored as completed');
});

When('the page is reloaded', async function () {
  const seed = {};
  const ls = this.localStorage;
  for (let i = 0; i < ls.length; i++) {
    const k = ls.key(i);
    seed[k] = ls.getItem(k);
  }
  await this.disposeApp();
  this.loadApp(seed);
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

Then('the todo {string} is visible', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  assert.strictEqual(li.hidden, false, 'todo ' + title + ' should be visible');
});

Then('the todo {string} is hidden', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' should exist to be hidden');
  assert.strictEqual(li.hidden, true, 'todo ' + title + ' should be hidden');
});

Then('the {string} filter link has the {string} class', function (name, cls) {
  const links = this.document.querySelectorAll('.filters a');
  let found = null;
  for (const a of links) {
    if (a.textContent.trim() === name) found = a;
  }
  assert(found, 'filter link ' + name + ' not found');
  assert(found.classList.contains(cls), 'filter link ' + name + ' should have class ' + cls);
});

Then(
  'the localStorage key {string} holds an array whose items conform to the {string} schema in {string}',
  function (key, schemaName, schemaPath) {
    const data = readStore(this, key);
    const schema = JSON.parse(fs.readFileSync(path.resolve(ROOT, schemaPath), 'utf8'));
    validateTodoRecord(data, schema);
  }
);

function validateTodoRecord(data, schema) {
  const name = schema.title || 'schema';
  assert(Array.isArray(data), name + ': expected an array');

  const itemSchema = schema.items;
  const required = itemSchema.required || [];
  const props = itemSchema.properties || {};

  data.forEach((item, i) => {
    assert(item && typeof item === 'object' && !Array.isArray(item), name + ': item ' + i + ' is not an object');

    required.forEach((k) => {
      assert(k in item, name + ': item ' + i + ' missing required property "' + k + '"');
    });

    const idTypes = Array.isArray(itemSchema.properties.id.type)
      ? itemSchema.properties.id.type
      : [itemSchema.properties.id.type];
    assert(
      idTypes.some((t) => typeof item.id === t),
      name + ': item ' + i + ' id has wrong type'
    );
    assert.strictEqual(typeof item.title, props.title.type, name + ': item ' + i + ' title has wrong type');
    assert.strictEqual(
      typeof item.completed,
      props.completed.type,
      name + ': item ' + i + ' completed has wrong type'
    );

    Object.keys(item).forEach((k) => {
      assert(k in props, name + ': item ' + i + ' has unexpected property "' + k + '"');
    });
  });
}

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp(seed) {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);
    // Preserved across a simulated reload: happy-dom does not share localStorage between
    // Window instances, so the reload step copies the prior window's localStorage in here
    // before the app evaluates, letting persistence/reload scenarios exercise the real path.
    this.appSource = appSource;

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    if (seed) {
      for (const k of Object.keys(seed)) this.window.localStorage.setItem(k, seed[k]);
    }
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

/* TodoMVC vanilla JS implementation.
 *
 * Reads and writes todos to localStorage under `todos-vanilla`, one record per item with
 * the shape { id, title, completed }. Editing state is never persisted. Routing is hash
 * based (#/, #/active, #/completed); the active route is persisted under `todos-vanilla-route`
 * so it survives a reload.
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla';
  var ROUTE_KEY = 'todos-vanilla-route';

  var w = window;
  var doc = document;

  var newTodoInput = doc.querySelector('.new-todo');
  var main = doc.getElementById('main');
  var footer = doc.getElementById('footer');
  var list = doc.querySelector('.todo-list');
  var toggleAll = doc.getElementById('toggle-all');
  var clearCompleted = doc.querySelector('.clear-completed');
  var count = doc.querySelector('.todo-count');
  var filters = doc.querySelector('.filters');

  /** @planks("the localStorage key {string} contains a record with title {string}") */
  /** @planks("the todo {string} is stored as active") */
  /** @planks("the todo {string} is stored as completed") */
  /** @planks("the localStorage key {string} holds an array whose items conform to the {string} schema in {string}") */
  function load() {
    var raw = w.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    try {
      var parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }

  function save(todos) {
    w.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function nextId(todos) {
    var max = 0;
    for (var i = 0; i < todos.length; i++) {
      var id = todos[i].id;
      if (typeof id === 'number' && id > max) max = id;
    }
    return max + 1;
  }

  function getRoute() {
    var r = w.location.hash;
    if (!r || r === '#') r = w.localStorage.getItem(ROUTE_KEY) || '#/';
    return r;
  }

  function setRoute(r) {
    w.localStorage.setItem(ROUTE_KEY, r);
  }

  /** @planks("the {string} section is hidden") */
  /** @planks("the todo {string} is present in the list") */
  /** @planks("the todo-count shows {string}") */
  /** @planks("the todo {string} has the {string} class") */
  /** @planks("the todo {string} does not have the {string} class") */
  /** @planks("the toggle-all checkbox is checked") */
  /** @planks("the toggle-all checkbox is unchecked") */
  /** @planks("every todo item has a {string} button") */
  /** @planks("the clear-completed button is hidden") */
  /** @planks("the {string} filter link has the {string} class") */
  /** @planks("the todo {string} is visible") */
  /** @planks("the todo {string} is hidden") */
  /** @planks("the new-todo input is empty") */
  /** @planks("no todo item is present in the list") */
  function render() {
    var todos = load();
    var route = getRoute();

    list.innerHTML = '';
    todos.forEach(function (t) {
      var li = doc.createElement('li');
      if (t.completed) li.className = 'completed';

      var view = doc.createElement('div');
      view.className = 'view';
      var toggle = doc.createElement('input');
      toggle.className = 'toggle';
      toggle.type = 'checkbox';
      toggle.checked = t.completed;
      var label = doc.createElement('label');
      label.textContent = t.title;
      var destroy = doc.createElement('button');
      destroy.className = 'destroy';
      view.appendChild(toggle);
      view.appendChild(label);
      view.appendChild(destroy);

      var edit = doc.createElement('input');
      edit.className = 'edit';
      edit.value = t.title;

      li.appendChild(view);
      li.appendChild(edit);

      var hidden =
        (route === '#/active' && t.completed) ||
        (route === '#/completed' && !t.completed);
      if (hidden) li.hidden = true;

      list.appendChild(li);
    });

    var hasTodos = todos.length > 0;
    main.hidden = !hasTodos;
    footer.hidden = !hasTodos;

    var allCompleted = hasTodos && todos.every(function (t) { return t.completed; });
    toggleAll.checked = allCompleted;

    var active = todos.filter(function (t) { return !t.completed; }).length;
    var word = active === 1 ? 'item' : 'items';
    count.innerHTML = '<strong>' + active + '</strong> ' + word + ' left';

    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearCompleted.hidden = !hasCompleted;

    var links = filters.querySelectorAll('a');
    for (var i = 0; i < links.length; i++) {
      var href = links[i].getAttribute('href');
      if (
        (route === '#/' && href === '#/') ||
        (route === '#/active' && href === '#/active') ||
        (route === '#/completed' && href === '#/completed')
      ) {
        links[i].classList.add('selected');
      } else {
        links[i].classList.remove('selected');
      }
    }
  }

  /** @planks("the new-todo input is focused") */
  /** @planks("the global flag {string} is set to a truthy value") */
  function init() {
    newTodoInput.focus();
    render();
    w.appHasStarted = true;
  }

  /** @planks("the user adds the todo {string}") */
  /** @planks("the user enters {string} in the new-todo input and presses Enter") */
  function handleNewTodo(e) {
    if (e.key !== 'Enter') return;
    var value = newTodoInput.value.trim();
    if (value) {
      var todos = load();
      todos.push({ id: nextId(todos), title: value, completed: false });
      save(todos);
    }
    newTodoInput.value = '';
    render();
  }

  /** @planks("the user clicks the checkbox of {string}") */
  function handleToggle(e) {
    var toggle = e.target.closest ? e.target.closest('.toggle') : null;
    if (!toggle) return;
    var li = toggle.closest('li');
    var title = li.querySelector('label').textContent;
    var todos = load();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === title) {
        todos[i].completed = toggle.checked;
        break;
      }
    }
    save(todos);
    render();
  }

  /** @planks("the user clicks the toggle-all checkbox") */
  function handleToggleAll() {
    var todos = load();
    for (var i = 0; i < todos.length; i++) todos[i].completed = toggleAll.checked;
    save(todos);
    render();
  }

  /** @planks("the user double-clicks the label of {string}") */
  /** @planks("the edit input of {string} is focused") */
  function handleDblClick(e) {
    var label = e.target.closest ? e.target.closest('label') : null;
    if (!label) return;
    var li = label.closest('li');
    li.classList.add('editing');
    li.querySelector('.edit').focus();
  }

  /** @planks("the user edits the label of {string} to {string} and presses Enter") */
  /** @planks("the user edits the label of {string} to {string} and blurs") */
  /** @planks("the user edits the label of {string} to {string} and presses Escape") */
  /** @planks("the user clears the edit input of {string} and presses Enter") */
  /** @planks("the todo {string} is not in editing mode") */
  function commitEdit(li, raw) {
    var title = li.querySelector('label').textContent;
    var value = raw.trim();
    var todos = load();
    if (value === '') {
      var remaining = todos.filter(function (t) { return t.title !== title; });
      save(remaining);
      render();
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === title) {
        todos[i].title = value;
        break;
      }
    }
    save(todos);
    render();
  }

  function handleEditKeydown(e) {
    var edit = e.target.closest ? e.target.closest('.edit') : null;
    if (!edit) return;
    var li = edit.closest('li');
    if (e.key === 'Enter') {
      commitEdit(li, edit.value);
    } else if (e.key === 'Escape') {
